class _DirectInjectionParameter(typing.NamedTuple):
    argument_index: int
    field_name: str
    provider: AbstractProvider[typing.Any]
    scope_context_init_order: tuple[AbstractProvider[typing.Any], ...]


class _StringInjectionParameter(typing.NamedTuple):
    argument_index: int
    field_name: str
